#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "wf_r17_post7a00.h"

typedef struct { wf_r17_fg0_write_t w[156]; size_t n; int block; } sink_t;
static wf_status_t sink(wf_runtime_t *rt,const wf_r17_fg0_write_t *w,size_t n,void *u){sink_t*s=u;(void)rt;if(s->block)return WF_BLOCKED;assert(n<=156u);memcpy(s->w,w,n*sizeof(*w));s->n=n;return WF_OK;}
static void init(wf_runtime_t*r,wf_r17_post7_ctx_t*c,sink_t*s){memset(r,0,sizeof(*r));memset(c,0,sizeof(*c));memset(s,0,sizeof(*s));wf_r17_m68k_software_reset(&r->m68k_regs);r->m68k_regs.d[0]=0xAAAA1111u;r->m68k_regs.d[1]=0xBBBB2222u;r->m68k_regs.d[2]=0xCCCC3333u;c->fg0_batch=sink;c->user=s;}
static void test_early_gates(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_167b=1u;assert(wf_r17_owner_899c(&r,&c)==WF_OK);assert(s.n==0);assert(r.m68k_regs.d[0]==0xAAAA1111u);init(&r,&c,&s);assert(wf_r17_owner_899c(&r,&c)==WF_OK);assert(s.n==0);assert(r.g.global_167a==0&&r.g.global_167b==0);}
static void test_normal_byte_batch(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_167a=0x80u;r.g.global_00aa=0u;r.g.global_00b2=0u;assert(wf_r17_owner_899c(&r,&c)==WF_OK);assert(s.n==156u);assert(s.w[0].addr==0x000c1009u&&s.w[0].width==1u&&s.w[0].value==0x00u);assert(s.w[1].addr==0x000c100bu&&s.w[1].width==1u&&s.w[1].value==0xe4u);assert(s.w[2].addr==0x000c100du&&s.w[2].value==0x01u);/* row1 starts after 7 cells */assert(s.w[14].addr==0x000c1109u&&s.w[14].value==0x0eu);assert(r.g.global_00aa==1u&&r.g.global_00b2==0u);assert(r.g.global_167b==0x80u&&r.g.global_167a==0u);assert(r.m68k_regs.d[0]==0xAAAA000Du);assert(r.m68k_regs.d[1]==0u);assert(r.m68k_regs.d[2]==0xCCCCFFFFu);}
static void test_prev_bit7_clear_mode_and_toggle(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_167b=0x80u;r.g.global_167a=0u;r.g.global_00aa=1u;r.g.global_00b2=0u;assert(wf_r17_owner_899c(&r,&c)==WF_OK);assert(s.n==78u);assert(s.w[0].addr==0x000c1008u&&s.w[0].width==4u&&s.w[0].value==0xff00ff00u);assert(r.g.global_00aa==0u&&r.g.global_00b2==1u);assert(r.g.global_167b==0x40u&&r.g.global_167a==0u);}
static void test_alternate_descriptor_lowbyte(void){wf_runtime_t r;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_167a=0x80u;r.g.global_00b2=1u;assert(wf_r17_owner_899c(&r,&c)==WF_OK);assert(s.n==156u);assert(s.w[0].value==0x07u);assert(s.w[14].value==0x15u);}
static void test_rollback(void){wf_runtime_t r,b;wf_r17_post7_ctx_t c;sink_t s;init(&r,&c,&s);r.g.global_167a=0x80u;r.g.global_00aa=1u;s.block=1;b=r;assert(wf_r17_owner_899c(&r,&c)==WF_BLOCKED);assert(r.g.global_167a==b.g.global_167a&&r.g.global_167b==b.g.global_167b&&r.g.global_00aa==b.g.global_00aa&&r.g.global_00b2==b.g.global_00b2);assert(memcmp(&r.m68k_regs,&b.m68k_regs,sizeof(r.m68k_regs))==0);assert(c.blocked_dependency_rom==0x000c1008u);}
int main(void){test_early_gates();test_normal_byte_batch();test_prev_bit7_clear_mode_and_toggle();test_alternate_descriptor_lowbyte();test_rollback();puts("PASS $899C raw FG0 producer ROM contract");return 0;}
